import java.lang.annotation.*;
import java.lang.reflect.*;
import java.util.*;

public class CalculatorTestRunner {
    // Stand-ins for org.junit.jupiter.api / .params annotations (JUnit is not on the classpath here)
    @Retention(RetentionPolicy.RUNTIME) @interface Test {}
    @Retention(RetentionPolicy.RUNTIME) @interface ParameterizedTest {}
    @Retention(RetentionPolicy.RUNTIME) @interface ValueSource { int[] ints(); }
    @Retention(RetentionPolicy.RUNTIME) @interface DisplayName { String value(); }
    @Retention(RetentionPolicy.RUNTIME) @interface BeforeEach {}

    // Stand-ins for org.junit.jupiter.api.Assertions (same argument order: expected first)
    static void assertEquals(long expected, long actual) {
        if (expected != actual) throw new AssertionError("expected: <" + expected + "> but was: <" + actual + ">");
    }
    static void assertEquals(double expected, double actual, double delta) {
        if (Math.abs(expected - actual) > delta) throw new AssertionError("expected: <" + expected + "> but was: <" + actual + ">");
    }
    static void assertTrue(boolean condition) {
        if (!condition) throw new AssertionError("expected: <true> but was: <false>");
    }
    static void assertThrows(Class<? extends Throwable> type, Runnable code) {
        try { code.run(); } catch (Throwable t) { if (type.isInstance(t)) return; throw t; }
        throw new AssertionError("expected an exception, but nothing was thrown");
    }

    // The class under test
    static class Calculator {
        int add(int a, int b) { return a + b; }
        double divide(double a, double b) {
            if (b == 0) throw new ArithmeticException("/ by zero");
            return a / b;
        }
        boolean isEven(int n) { return n % 2 == 0; }
        int max(int... values) {
            int best = 0; // BUG: should start at values[0]; the test below catches it
            for (int v : values) best = Math.max(best, v);
            return best;
        }
    }

    public static class CalculatorTest {
        private Calculator calculator;

        @BeforeEach void setUp() { calculator = new Calculator(); }

        @Test @DisplayName("add two numbers")
        void addition() { assertEquals(5, calculator.add(2, 3)); assertEquals(0, calculator.add(-1, 1)); }

        @Test @DisplayName("divide within delta")
        void division() { assertEquals(2.5, calculator.divide(10, 4), 1e-9); }

        @Test @DisplayName("divide by zero throws")
        void divideByZero() { assertThrows(ArithmeticException.class, () -> calculator.divide(10, 0)); }

        @ParameterizedTest @ValueSource(ints = {2, 4, 6, 8}) @DisplayName("isEven")
        void evens(int n) { assertTrue(calculator.isEven(n)); }

        @Test @DisplayName("max of all-negative array")
        void maxOfNegatives() { assertEquals(-2, calculator.max(-5, -2, -9)); }
    }

    // A tiny runner: discover annotated methods, new instance per test, @BeforeEach, then report
    public static void main(String[] args) throws Exception {
        Class<?> cls = CalculatorTest.class;
        List<Method> tests = Arrays.stream(cls.getDeclaredMethods())
                .filter(m -> m.isAnnotationPresent(Test.class) || m.isAnnotationPresent(ParameterizedTest.class))
                .sorted(Comparator.comparing((Method m) -> m.getAnnotation(DisplayName.class).value()))
                .toList(); // sorted only to make this demo deterministic; never rely on test order
        Method setUp = cls.getDeclaredMethod("setUp");
        int run = 0, failed = 0;
        System.out.println(cls.getSimpleName());
        for (Method test : tests) {
            String name = test.getAnnotation(DisplayName.class).value();
            List<Object[]> invocations = new ArrayList<>();
            if (test.isAnnotationPresent(ValueSource.class)) {
                for (int v : test.getAnnotation(ValueSource.class).ints()) invocations.add(new Object[]{v});
            } else {
                invocations.add(new Object[0]);
            }
            for (int i = 0; i < invocations.size(); i++) {
                Object[] arguments = invocations.get(i);
                String label = arguments.length == 0 ? name : name + " [" + (i + 1) + "] " + arguments[0];
                Object instance = cls.getDeclaredConstructor().newInstance(); // fresh object for every test
                run++;
                try {
                    setUp.invoke(instance);
                    test.invoke(instance, arguments);
                    System.out.println("  PASS  " + label);
                } catch (InvocationTargetException e) {
                    failed++;
                    System.out.println("  FAIL  " + label);
                    System.out.println("        " + e.getCause().getMessage());
                }
            }
        }
        System.out.println("Tests run: " + run + ", passed: " + (run - failed) + ", failed: " + failed);
    }
}

