#include <algorithm>
#include <charconv>
#include <cmath>
#include <functional>
#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>

// Stand-ins for org.junit.jupiter.api.Assertions (expected first, as in JUnit)
struct AssertionError : std::runtime_error { using std::runtime_error::runtime_error; };

std::string show(double x) {  // shortest text that round-trips, like Java's Double.toString
    char buf[32];
    auto res = std::to_chars(buf, buf + sizeof buf, x);
    return std::string(buf, res.ptr);
}
void assertEquals(long expected, long actual) {
    if (expected != actual)
        throw AssertionError("expected: <" + std::to_string(expected) + "> but was: <" + std::to_string(actual) + ">");
}
void assertEquals(double expected, double actual, double delta) {
    if (std::fabs(expected - actual) > delta)
        throw AssertionError("expected: <" + show(expected) + "> but was: <" + show(actual) + ">");
}
void assertTrue(bool condition) {
    if (!condition) throw AssertionError("expected: <true> but was: <false>");
}
template <typename E> void assertThrows(const std::function<void()>& code) {
    try { code(); } catch (const E&) { return; }
    throw AssertionError("expected an exception, but nothing was thrown");
}

// The class under test
struct Calculator {
    int add(int a, int b) const { return a + b; }
    double divide(double a, double b) const {
        if (b == 0) throw std::domain_error("/ by zero");
        return a / b;
    }
    bool isEven(int n) const { return n % 2 == 0; }
    int max(const std::vector<int>& values) const {
        int best = 0;  // BUG: should start at values[0]; the test below catches it
        for (int v : values) best = std::max(best, v);
        return best;
    }
};

struct CalculatorTest {
    Calculator calculator;
    void setUp() { calculator = Calculator(); }  // plays the role of @BeforeEach
    void addition(int) { assertEquals(5, calculator.add(2, 3)); assertEquals(0, calculator.add(-1, 1)); }
    void division(int) { assertEquals(2.5, calculator.divide(10, 4), 1e-9); }
    void divideByZero(int) { assertThrows<std::domain_error>([&] { calculator.divide(10, 0); }); }
    void evens(int n) { assertTrue(calculator.isEven(n)); }
    void maxOfNegatives(int) { assertEquals(-2, calculator.max({-5, -2, -9})); }
};

// C++ has no annotations, so the test metadata is a table (like @Test/@DisplayName/@ValueSource)
struct TestSpec {
    std::string name;
    void (CalculatorTest::*method)(int);
    std::vector<int> values;  // empty = not parameterized
};

int main() {
    std::vector<TestSpec> tests = {
        {"add two numbers", &CalculatorTest::addition, {}},
        {"divide within delta", &CalculatorTest::division, {}},
        {"divide by zero throws", &CalculatorTest::divideByZero, {}},
        {"isEven", &CalculatorTest::evens, {2, 4, 6, 8}},
        {"max of all-negative array", &CalculatorTest::maxOfNegatives, {}},
    };
    std::sort(tests.begin(), tests.end(), [](auto& a, auto& b) { return a.name < b.name; });  // deterministic demo

    int run = 0, failed = 0;
    std::cout << "CalculatorTest\n";
    for (const auto& spec : tests) {
        size_t count = spec.values.empty() ? 1 : spec.values.size();
        for (size_t i = 0; i < count; ++i) {
            std::string label = spec.values.empty()
                ? spec.name : spec.name + " [" + std::to_string(i + 1) + "] " + std::to_string(spec.values[i]);
            CalculatorTest instance;  // fresh object for every test
            ++run;
            try {
                instance.setUp();
                (instance.*spec.method)(spec.values.empty() ? 0 : spec.values[i]);
                std::cout << "  PASS  " << label << "\n";
            } catch (const AssertionError& e) {
                ++failed;
                std::cout << "  FAIL  " << label << "\n        " << e.what() << "\n";
            }
        }
    }
    std::cout << "Tests run: " << run << ", passed: " << run - failed << ", failed: " << failed << "\n";
}

