# Stand-ins for JUnit features: decorators play the role of @Test, @DisplayName, @ValueSource


def test(display_name):
    def mark(fn):
        fn.display_name = display_name
        return fn
    return mark


def value_source(*values):  # like @ParameterizedTest @ValueSource(ints = {...})
    def mark(fn):
        fn.values = values
        return fn
    return mark


def assert_equals(expected, actual, delta=None):  # expected first, as in JUnit
    ok = abs(expected - actual) <= delta if delta is not None else expected == actual
    if not ok:
        raise AssertionError(f"expected: <{expected}> but was: <{actual}>")


def assert_true(condition):
    if not condition:
        raise AssertionError("expected: <true> but was: <false>")


def assert_throws(exc_type, code):
    try:
        code()
    except exc_type:
        return
    raise AssertionError("expected an exception, but nothing was thrown")


class Calculator:  # the class under test
    def add(self, a, b): return a + b

    def divide(self, a, b):
        if b == 0:
            raise ZeroDivisionError("/ by zero")
        return a / b

    def is_even(self, n): return n % 2 == 0

    def max(self, *values):
        best = 0  # BUG: should start at values[0]; the test below catches it
        for v in values:
            best = max(best, v)
        return best


class CalculatorTest:
    def set_up(self):  # plays the role of @BeforeEach
        self.calculator = Calculator()

    @test("add two numbers")
    def addition(self):
        assert_equals(5, self.calculator.add(2, 3))
        assert_equals(0, self.calculator.add(-1, 1))

    @test("divide within delta")
    def division(self):
        assert_equals(2.5, self.calculator.divide(10, 4), delta=1e-9)

    @test("divide by zero throws")
    def divide_by_zero(self):
        assert_throws(ZeroDivisionError, lambda: self.calculator.divide(10, 0))

    @test("isEven")
    @value_source(2, 4, 6, 8)
    def evens(self, n):
        assert_true(self.calculator.is_even(n))

    @test("max of all-negative array")
    def max_of_negatives(self):
        assert_equals(-2, self.calculator.max(-5, -2, -9))


def run_tests(cls):
    """A tiny runner: discover marked methods, new instance per test, set_up, then report."""
    tests = sorted((f for f in vars(cls).values() if hasattr(f, "display_name")),
                   key=lambda f: f.display_name)  # sorted for a deterministic demo only
    run = failed = 0
    print(cls.__name__)
    for fn in tests:
        invocations = [(v,) for v in fn.values] if hasattr(fn, "values") else [()]
        for i, args in enumerate(invocations, start=1):
            label = f"{fn.display_name} [{i}] {args[0]}" if args else fn.display_name
            instance = cls()  # fresh object for every test
            run += 1
            try:
                instance.set_up()
                fn(instance, *args)
                print(f"  PASS  {label}")
            except AssertionError as e:
                failed += 1
                print(f"  FAIL  {label}")
                print(f"        {e}")
    print(f"Tests run: {run}, passed: {run - failed}, failed: {failed}")


run_tests(CalculatorTest)

