    if (b === 0) throw new RangeError('/ by zero'); // JS would silently return Infinity
    return a / b;
  }
  isEven(n) { return n % 2 === 0; }
  max(...values) {
    let best = 0; // BUG: should start at values[0]; the test below catches it
    for (const v of values) best = Math.max(best, v);
