// JavaScript has no annotations, so the test metadata is a table (like @Test/@DisplayName/@ValueSource)
const tests = [
  { name: 'add two numbers', method: 'addition' },
  { name: 'divide within delta', method: 'division' },
  { name: 'divide by zero throws', method: 'divideByZero' },
  { name: 'isEven', method: 'evens', values: [2, 4, 6, 8] },
  { name: 'max of all-negative array', method: 'maxOfNegatives' },
];

// A tiny runner: new instance per test, setUp, then report
function runTests(cls, specs) {
  let run = 0;
  let failed = 0;
  console.log(cls.name);
  for (const spec of [...specs].sort((a, b) => (a.name < b.name ? -1 : 1))) { // deterministic demo order
    const invocations = spec.values ? spec.values.map((v) => [v]) : [[]];
    invocations.forEach((args, i) => {
      const label = args.length ? `${spec.name} [${i + 1}] ${args[0]}` : spec.name;
      const instance = new cls(); // fresh object for every test
      run += 1;
      try {
        instance.setUp();
        instance[spec.method](...args);
        console.log(`  PASS  ${label}`);
