import java.lang.annotation.*;
import java.lang.reflect.*;
import java.util.*;

public class WordCounterTestDemo {
    // Stand-ins for org.junit.jupiter.api.Test and DisplayName
    @Retention(RetentionPolicy.RUNTIME) @interface Test {}
    @Retention(RetentionPolicy.RUNTIME) @interface DisplayName { String value(); }

    // Stand-in for Assertions.assertEquals(expected, actual)
    static void assertEquals(int expected, int actual) {
        if (expected != actual) throw new AssertionError("expected: <" + expected + "> but was: <" + actual + ">");
    }

    // Code under test: counts words, but only treats ' ' as a separator (a real bug)
    static int countWords(String text) {
        int words = 0;
        boolean inWord = false;
        for (char c : text.toCharArray()) {
            if (c == ' ') inWord = false;
            else if (!inWord) { inWord = true; words++; }
        }
        return words;
    }

    // A test class: plain void, no-argument methods marked with @Test. Each follows Arrange-Act-Assert.
    public static class WordCounterTest {
        @Test @DisplayName("counts words separated by spaces")
        void countsWordsSeparatedBySpaces() {
            String text = "unit tests are fun";      // arrange
            int result = countWords(text);           // act
            assertEquals(4, result);                 // assert
        }

        @Test @DisplayName("empty string has zero words")
        void emptyStringHasZeroWords() { assertEquals(0, countWords("")); }

        @Test @DisplayName("ignores leading, trailing and repeated spaces")
        void ignoresExtraSpaces() { assertEquals(2, countWords("  two   words ")); }

        @Test @DisplayName("treats a tab as a separator")
        void tabIsASeparator() { assertEquals(2, countWords("one\ttwo")); }
    }

    // What the JUnit engine does: find @Test methods, run each one in isolation, collect results
    public static void main(String[] args) throws Exception {
        Class<?> cls = WordCounterTest.class;
        List<Method> tests = Arrays.stream(cls.getDeclaredMethods())
                .filter(m -> m.isAnnotationPresent(Test.class))
                .sorted(Comparator.comparing(Method::getName)) // deterministic order for the demo
                .toList();
        int failed = 0;
        System.out.println(cls.getSimpleName());
        for (Method test : tests) {
            String name = test.getAnnotation(DisplayName.class).value();
            try {
                test.invoke(cls.getDeclaredConstructor().newInstance());
                System.out.println("  PASS  " + name);
            } catch (InvocationTargetException e) { // a failing test does not stop the others
                failed++;
                System.out.println("  FAIL  " + name);
                System.out.println("        " + e.getCause().getMessage());
            }
        }
        System.out.println("Tests run: " + tests.size() + ", passed: " + (tests.size() - failed) + ", failed: " + failed);
    }
}

