import java.util.*;

public class AssertionsTour {
    // Minimal stand-ins for org.junit.jupiter.api.Assertions, with JUnit's message format
    static void assertEquals(Object expected, Object actual) {
        if (!Objects.equals(expected, actual))
            throw new AssertionError("expected: <" + expected + "> but was: <" + actual + ">");
    }
    static void assertEquals(double expected, double actual, double delta) {
        if (Math.abs(expected - actual) > delta)
            throw new AssertionError("expected: <" + expected + "> but was: <" + actual + ">");
    }
    static void assertTrue(boolean condition) {
        if (!condition) throw new AssertionError("expected: <true> but was: <false>");
    }
    static <T extends Throwable> T assertThrows(Class<T> type, Runnable code) {
        try { code.run(); } catch (Throwable t) { if (type.isInstance(t)) return type.cast(t); throw t; }
        throw new AssertionError("expected an exception, but nothing was thrown");
    }
    static void assertAll(Runnable... checks) { // runs every check, then reports all failures together
        List<String> failures = new ArrayList<>();
        for (Runnable check : checks) {
            try { check.run(); } catch (AssertionError e) { failures.add(e.getMessage()); }
        }
        if (!failures.isEmpty())
            throw new AssertionError("Multiple Failures (" + failures.size() + " failures)\n    " + String.join("\n    ", failures));
    }

    // Code under test
    static boolean isPrime(int n) {
        for (int d = 2; d * d <= n; d++) if (n % d == 0) return false;
        return n >= 2;
    }
    static int parsePositive(String s) {
        int value = Integer.parseInt(s);
        if (value <= 0) throw new IllegalArgumentException("must be positive: " + value);
        return value;
    }

    static void check(String label, Runnable assertion) {
        try {
            assertion.run();
            System.out.println(label + ": passed");
        } catch (AssertionError e) {
            System.out.println(label + ": FAILED " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        check("assertEquals(4, 2 + 2)", () -> assertEquals(4, 2 + 2));
        check("assertEquals(0.3, 0.1 + 0.2)", () -> assertEquals(0.3, 0.1 + 0.2)); // exact double compare
        check("assertEquals(0.3, 0.1 + 0.2, 1e-9)", () -> assertEquals(0.3, 0.1 + 0.2, 1e-9));
        check("assertTrue(isPrime(7))", () -> assertTrue(isPrime(7)));
        check("assertTrue(isPrime(9))", () -> assertTrue(isPrime(9)));
        check("assertThrows(parsePositive(\"-5\"))", () -> {
            IllegalArgumentException e = assertThrows(IllegalArgumentException.class, () -> parsePositive("-5"));
            assertEquals("must be positive: -5", e.getMessage()); // you can also check the message
        });
        check("assertThrows(parsePositive(\"12\"))",
              () -> assertThrows(IllegalArgumentException.class, () -> parsePositive("12")));

        int itemsInCart = 4; // the real (actual) value; the test expects 5
        check("swapped assertEquals(itemsInCart, 5)", () -> assertEquals(itemsInCart, 5)); // misleading message

        String name = "ana";
        int age = 19;
        String city = "Lima";
        check("assertAll(name, age, city)", () -> assertAll(
            () -> assertEquals("Ana", name),
            () -> assertEquals(19, age),
            () -> assertEquals("Quito", city)));
    }
