// Minimal stand-ins for JUnit's Assertions, with JUnit's message format
struct AssertionError : std::runtime_error { using std::runtime_error::runtime_error; };

std::string show(const std::string& s) { return s; }
std::string show(int x) { return std::to_string(x); }
std::string show(double x) {  // shortest text that round-trips, like Java's Double.toString
    char buf[32];
    return std::string(buf, std::to_chars(buf, buf + sizeof buf, x).ptr);
}

template <typename T> void assertEquals(const T& expected, const T& actual) {
    if (!(expected == actual))
        throw AssertionError("expected: <" + show(expected) + "> but was: <" + show(actual) + ">");
}
void assertEquals(double expected, double actual, double delta) {
    if (std::fabs(expected - actual) > delta)
        throw AssertionError("expected: <" + show(expected) + "> but was: <" + show(actual) + ">");
}
void assertTrue(bool condition) {
    if (!condition) throw AssertionError("expected: <true> but was: <false>");
}
template <typename E> E assertThrows(const std::function<void()>& code) {
    try { code(); } catch (const E& e) { return e; }  // return it so its message can be checked
    throw AssertionError("expected an exception, but nothing was thrown");
}
void assertAll(const std::vector<std::function<void()>>& checks) {  // run all, report all failures
    std::vector<std::string> failures;
    for (const auto& c : checks) {
        try { c(); } catch (const AssertionError& e) { failures.push_back(e.what()); }
    }
    if (failures.empty()) return;
    std::string msg = "Multiple Failures (" + std::to_string(failures.size()) + " failures)";
    for (const auto& f : failures) msg += "\n    " + f;
    throw AssertionError(msg);
}

// Code under test
bool isPrime(int n) {
    for (int d = 2; d * d <= n; ++d) if (n % d == 0) return false;
    return n >= 2;
}
int parsePositive(const std::string& s) {
    int value = std::stoi(s);
    if (value <= 0) throw std::invalid_argument("must be positive: " + std::to_string(value));
    return value;
}

void check(const std::string& label, const std::function<void()>& assertion) {
    try {
        assertion();
        std::cout << label << ": passed\n";
    } catch (const AssertionError& e) {
        std::cout << label << ": FAILED " << e.what() << "\n";
    }
}

int main() {
    check("assertEquals(4, 2 + 2)", [] { assertEquals(4, 2 + 2); });
    check("assertEquals(0.3, 0.1 + 0.2)", [] { assertEquals<double>(0.3, 0.1 + 0.2); });  // exact compare
    check("assertEquals(0.3, 0.1 + 0.2, 1e-9)", [] { assertEquals(0.3, 0.1 + 0.2, 1e-9); });
    check("assertTrue(isPrime(7))", [] { assertTrue(isPrime(7)); });
    check("assertTrue(isPrime(9))", [] { assertTrue(isPrime(9)); });
    check("assertThrows(parsePositive(\"-5\"))", [] {
        auto e = assertThrows<std::invalid_argument>([] { parsePositive("-5"); });
        assertEquals<std::string>("must be positive: -5", e.what());  // you can also check the message
    });
    check("assertThrows(parsePositive(\"12\"))", [] { assertThrows<std::invalid_argument>([] { parsePositive("12"); }); });

    int itemsInCart = 4;  // the real (actual) value; the test expects 5
    check("swapped assertEquals(itemsInCart, 5)", [&] { assertEquals(itemsInCart, 5); });  // misleading message

    std::string name = "ana";
    int age = 19;
    std::string city = "Lima";
    check("assertAll(name, age, city)", [&] {
        assertAll({[&] { assertEquals<std::string>("Ana", name); },
                   [&] { assertEquals(19, age); },
                   [&] { assertEquals<std::string>("Quito", city); }});
    });
}

