# Minimal stand-ins for JUnit's Assertions, with JUnit's message format


def assert_equals(expected, actual, delta=None):
    ok = abs(expected - actual) <= delta if delta is not None else expected == actual
    if not ok:
        raise AssertionError(f"expected: <{expected}> but was: <{actual}>")


def assert_true(condition):
    if not condition:
        raise AssertionError("expected: <true> but was: <false>")


def assert_throws(exc_type, code):
    try:
        code()
    except exc_type as e:
        return e  # hand the exception back so its message can be checked
    raise AssertionError("expected an exception, but nothing was thrown")


def assert_all(*checks):
    """Runs every check, then reports all failures together."""
    failures = []
    for check_fn in checks:
        try:
            check_fn()
        except AssertionError as e:
            failures.append(str(e))
    if failures:
        raise AssertionError(f"Multiple Failures ({len(failures)} failures)\n    " + "\n    ".join(failures))


def is_prime(n):  # code under test
    return n >= 2 and all(n % d for d in range(2, int(n ** 0.5) + 1))


def parse_positive(s):  # code under test
    value = int(s)
    if value <= 0:
        raise ValueError(f"must be positive: {value}")
    return value


def check(label, assertion):
    try:
        assertion()
        print(f"{label}: passed")
    except AssertionError as e:
        print(f"{label}: FAILED {e}")


def throws_with_message():
    e = assert_throws(ValueError, lambda: parse_positive("-5"))
    assert_equals("must be positive: -5", str(e))  # you can also check the message


check("assertEquals(4, 2 + 2)", lambda: assert_equals(4, 2 + 2))
check("assertEquals(0.3, 0.1 + 0.2)", lambda: assert_equals(0.3, 0.1 + 0.2))  # exact float compare
check("assertEquals(0.3, 0.1 + 0.2, 1e-9)", lambda: assert_equals(0.3, 0.1 + 0.2, delta=1e-9))
check("assertTrue(isPrime(7))", lambda: assert_true(is_prime(7)))
check("assertTrue(isPrime(9))", lambda: assert_true(is_prime(9)))
check('assertThrows(parsePositive("-5"))', throws_with_message)
check('assertThrows(parsePositive("12"))', lambda: assert_throws(ValueError, lambda: parse_positive("12")))

items_in_cart = 4  # the real (actual) value; the test expects 5
check("swapped assertEquals(itemsInCart, 5)", lambda: assert_equals(items_in_cart, 5))  # misleading message

name, age, city = "ana", 19, "Lima"
check("assertAll(name, age, city)", lambda: assert_all(
    lambda: assert_equals("Ana", name),
    lambda: assert_equals(19, age),
    lambda: assert_equals("Quito", city)))

