import java.lang.annotation.*;
import java.lang.reflect.*;
import java.util.*;

public class LifecycleOrderDemo {
    // Stand-ins for the JUnit Jupiter lifecycle annotations
    @Retention(RetentionPolicy.RUNTIME) @interface BeforeAll {}
    @Retention(RetentionPolicy.RUNTIME) @interface BeforeEach {}
    @Retention(RetentionPolicy.RUNTIME) @interface Test {}
    @Retention(RetentionPolicy.RUNTIME) @interface AfterEach {}
    @Retention(RetentionPolicy.RUNTIME) @interface AfterAll {}

    public static class CartTest {
        static int instancesCreated = 0;       // static: shared by all instances
        private List<String> cart;
        private int testsInThisInstance = 0;   // instance field: starts at 0 in every new instance

        public CartTest() { System.out.println("new CartTest instance #" + (++instancesCreated)); }

        @BeforeAll static void openDatabase() { System.out.println("@BeforeAll   open shared test database (static, runs once)"); }
        @BeforeEach void createCart() { cart = new ArrayList<>(); System.out.println("  @BeforeEach  cart = new empty cart"); }
        @AfterEach void clearCart() { cart.clear(); System.out.println("  @AfterEach   cart cleared"); }
        @AfterAll static void closeDatabase() { System.out.println("@AfterAll    close shared test database (static, runs once)"); }

        @Test void addOneItem() { cart.add("pen"); report("add one item"); }
        @Test void addTwoItems() { cart.add("pen"); cart.add("book"); report("add two items"); }
        @Test void removeAnItem() { cart.add("pen"); cart.remove("pen"); report("remove an item"); }

        private void report(String name) {
            testsInThisInstance++;
            System.out.println("  @Test       " + name + ": size=" + cart.size() + ", testsInThisInstance=" + testsInThisInstance);
        }
    }

    static List<Method> annotated(Class<?> cls, Class<? extends Annotation> a) {
        return Arrays.stream(cls.getDeclaredMethods()).filter(m -> m.isAnnotationPresent(a))
                .sorted(Comparator.comparing(Method::getName)).toList();
    }

    // The order the JUnit engine uses (default Lifecycle.PER_METHOD)
    public static void main(String[] args) throws Exception {
        Class<CartTest> cls = CartTest.class;
        for (Method m : annotated(cls, BeforeAll.class)) m.invoke(null);       // static: no instance exists yet
        List<Method> tests = annotated(cls, Test.class);
        for (Method test : tests) {
            CartTest instance = cls.getDeclaredConstructor().newInstance();   // fresh instance per test
            for (Method m : annotated(cls, BeforeEach.class)) m.invoke(instance);
            try {
                test.invoke(instance);
            } finally {
                for (Method m : annotated(cls, AfterEach.class)) m.invoke(instance); // runs even if the test fails
            }
        }
        for (Method m : annotated(cls, AfterAll.class)) m.invoke(null);
        System.out.println("tests run: " + tests.size() + ", instances created: " + CartTest.instancesCreated);
    }
}

