// A mini runner that follows JUnit Jupiter's lifecycle order (default Lifecycle.PER_METHOD).
// GoogleTest has the same hooks: SetUpTestSuite, SetUp, TearDown, TearDownTestSuite.
struct CartTest {
    static inline int instancesCreated = 0;  // static: shared by all instances
    std::vector<std::string> cart;
    int testsInThisInstance = 0;  // instance field: starts at 0 in every new instance

    CartTest() { std::cout << "new CartTest instance #" << ++instancesCreated << "\n"; }

    static void beforeAll() { std::cout << "@BeforeAll   open shared test database (static, runs once)\n"; }
    void beforeEach() { cart.clear(); std::cout << "  @BeforeEach  cart = new empty cart\n"; }
    void afterEach() { cart.clear(); std::cout << "  @AfterEach   cart cleared\n"; }
    static void afterAll() { std::cout << "@AfterAll    close shared test database (static, runs once)\n"; }

    void addOneItem() { cart.push_back("pen"); report("add one item"); }
    void addTwoItems() { cart.push_back("pen"); cart.push_back("book"); report("add two items"); }
    void removeAnItem() {
        cart.push_back("pen");
        cart.erase(std::find(cart.begin(), cart.end(), "pen"));
        report("remove an item");
    }

    void report(const std::string& name) {
        ++testsInThisInstance;
        std::cout << "  @Test       " << name << ": size=" << cart.size()
                  << ", testsInThisInstance=" << testsInThisInstance << "\n";
    }
};

int main() {
    std::vector<std::pair<std::string, void (CartTest::*)()>> tests = {
        {"addOneItem", &CartTest::addOneItem},
        {"addTwoItems", &CartTest::addTwoItems},
        {"removeAnItem", &CartTest::removeAnItem},
    };
    CartTest::beforeAll();  // once, before any instance exists
    for (const auto& [name, method] : tests) {
        CartTest instance;  // fresh instance per test
        instance.beforeEach();
        (instance.*method)();
        instance.afterEach();  // a real runner calls this even when the test fails
    }
    CartTest::afterAll();
    std::cout << "tests run: " << tests.size() << ", instances created: " << CartTest::instancesCreated << "\n";
}

