    for name in tests:
        instance = cls()  # fresh instance per test
        instance.before_each()
        try:
            getattr(instance, name)()
        finally:
            instance.after_each()  # runs even if the test fails
    cls.after_all()
    print(f"tests run: {len(tests)}, instances created: {cls.instances_created}")


