import java.util.*;

public class MockRateProviderDemo {
    // The dependency: in production this calls a slow, paid exchange-rate web API
    interface RateProvider { double rate(String currency); }

    // The class under test only knows the interface, so a test can hand it a fake
    static class Converter {
        private final RateProvider rates;
        Converter(RateProvider rates) { this.rates = rates; }
        double toUsd(double amount, String currency) { return amount * rates.rate(currency); }
    }

    // A hand-written mock: what Mockito's mock(RateProvider.class) generates for you at run time.
    // It records every call and answers with stubbed values, or a default (0.0) when not stubbed.
    static class MockRateProvider implements RateProvider {
        private final Map<String, Double> stubs = new HashMap<>();
        final List<String> calls = new ArrayList<>();

        void when(String currency, double value) { stubs.put(currency, value); } // when(...).thenReturn(...)
        public double rate(String currency) {
            calls.add(currency);
            return stubs.getOrDefault(currency, 0.0);
        }
        void verify(String currency, int times) { // verify(mock, times(n)).rate(currency)
            long actual = calls.stream().filter(currency::equals).count();
            if (actual != times) {
                throw new AssertionError(actual == 0 ? "Wanted but not invoked: rates.rate(\"" + currency + "\")"
                        : "rates.rate(\"" + currency + "\") wanted " + times + " times but was " + actual);
            }
        }
    }

    static void check(String label, Runnable verification) {
        try { verification.run(); System.out.println(label + ": passed"); }
        catch (AssertionError e) { System.out.println(label + ": FAILED " + e.getMessage()); }
    }

    public static void main(String[] args) {
        MockRateProvider rates = new MockRateProvider();          // rates = mock(RateProvider.class)
        rates.when("EUR", 1.10);                                  // when(rates.rate("EUR")).thenReturn(1.10)
        System.out.println("when(rates.rate(\"EUR\")).thenReturn(1.10)");
        Converter converter = new Converter(rates);               // inject the mock

        double eur = converter.toUsd(100.00, "EUR");
        System.out.printf("toUsd(100.00, \"EUR\") = %.2f, within 1e-9 of 110.0: %b%n", eur, Math.abs(eur - 110.0) < 1e-9);
        double gbp = converter.toUsd(100.00, "GBP");
        System.out.printf("toUsd(100.00, \"GBP\") = %.2f  <- unstubbed call returned the default 0.0%n", gbp);

        check("verify(rates).rate(\"EUR\")", () -> rates.verify("EUR", 1));
        check("verify(rates, never()).rate(\"JPY\")", () -> rates.verify("JPY", 0));
        check("verify(rates).rate(\"JPY\")", () -> rates.verify("JPY", 1));
        System.out.println("recorded calls: " + rates.calls);
    }
}

