struct RateProvider {
    virtual ~RateProvider() = default;
    virtual double rate(const std::string& currency) = 0;
};

// The class under test only knows the interface, so a test can hand it a fake
class Converter {
    RateProvider& rates;
public:
    explicit Converter(RateProvider& r) : rates(r) {}
    double toUsd(double amount, const std::string& currency) { return amount * rates.rate(currency); }
};

// Records every call and answers with stubbed values, or a default (0.0) when not stubbed
struct MockRateProvider : RateProvider {
    std::map<std::string, double> stubs;
    std::vector<std::string> calls;
    void when(const std::string& currency, double value) { stubs[currency] = value; }  // thenReturn
    double rate(const std::string& currency) override {
        calls.push_back(currency);
        auto it = stubs.find(currency);
        return it == stubs.end() ? 0.0 : it->second;
    }
    void verify(const std::string& currency, long times) const {  // verify(rates, times(n))
        long actual = std::count(calls.begin(), calls.end(), currency);
        if (actual == times) return;
        throw AssertionError(actual == 0 ? "Wanted but not invoked: rates.rate(\"" + currency + "\")"
            : "rates.rate(\"" + currency + "\") wanted " + std::to_string(times) + " times but was " + std::to_string(actual));
    }
};

void check(const std::string& label, const std::function<void()>& verification) {
    try { verification(); std::printf("%s: passed\n", label.c_str()); }
    catch (const AssertionError& e) { std::printf("%s: FAILED %s\n", label.c_str(), e.what()); }
}

int main() {
    MockRateProvider rates;
    rates.when("EUR", 1.10);
    std::printf("when(rates.rate(\"EUR\")).thenReturn(1.10)\n");
    Converter converter(rates);  // inject the mock

    double eur = converter.toUsd(100.00, "EUR");
    std::printf("toUsd(100.00, \"EUR\") = %.2f, within 1e-9 of 110.0: %s\n", eur, std::fabs(eur - 110.0) < 1e-9 ? "true" : "false");
    double gbp = converter.toUsd(100.00, "GBP");
    std::printf("toUsd(100.00, \"GBP\") = %.2f  <- unstubbed call returned the default 0.0\n", gbp);

    check("verify(rates).rate(\"EUR\")", [&] { rates.verify("EUR", 1); });
    check("verify(rates, never()).rate(\"JPY\")", [&] { rates.verify("JPY", 0); });
    check("verify(rates).rate(\"JPY\")", [&] { rates.verify("JPY", 1); });
    std::printf("recorded calls: [");
    for (size_t i = 0; i < rates.calls.size(); ++i) std::printf("%s%s", i ? ", " : "", rates.calls[i].c_str());
    std::printf("]\n");
}

