from typing import Protocol

# Python ships unittest.mock (Mock, patch, assert_called_once_with); this hand-written mock
# shows what such a library does, with Mockito's defaults for unstubbed calls.


class RateProvider(Protocol):  # in production this calls a slow, paid exchange-rate web API
    def rate(self, currency: str) -> float: ...


class Converter:
    """The class under test only knows the interface, so a test can hand it a fake."""
    def __init__(self, rates: RateProvider):
        self.rates = rates

    def to_usd(self, amount, currency):
        return amount * self.rates.rate(currency)


class MockRateProvider:
    """Records every call and answers with stubbed values, or a default (0.0) when not stubbed."""
    def __init__(self):
        self._stubs: dict[str, float] = {}
        self.calls: list[str] = []

    def when(self, currency, value):  # when(rates.rate(currency)).thenReturn(value)
        self._stubs[currency] = value

    def rate(self, currency):
        self.calls.append(currency)
        return self._stubs.get(currency, 0.0)

    def verify(self, currency, times):  # verify(rates, times(n)).rate(currency)
        actual = self.calls.count(currency)
        if actual != times:
            raise AssertionError(f'Wanted but not invoked: rates.rate("{currency}")' if actual == 0
                                 else f'rates.rate("{currency}") wanted {times} times but was {actual}')


def check(label, verification):
    try:
        verification()
        print(f"{label}: passed")
    except AssertionError as e:
        print(f"{label}: FAILED {e}")


rates = MockRateProvider()
rates.when("EUR", 1.10)
print('when(rates.rate("EUR")).thenReturn(1.10)')
converter = Converter(rates)  # inject the mock

eur = converter.to_usd(100.00, "EUR")
print(f'toUsd(100.00, "EUR") = {eur:.2f}, within 1e-9 of 110.0: {str(abs(eur - 110.0) < 1e-9).lower()}')
gbp = converter.to_usd(100.00, "GBP")
print(f'toUsd(100.00, "GBP") = {gbp:.2f}  <- unstubbed call returned the default 0.0')

check('verify(rates).rate("EUR")', lambda: rates.verify("EUR", 1))
check('verify(rates, never()).rate("JPY")', lambda: rates.verify("JPY", 0))
check('verify(rates).rate("JPY")', lambda: rates.verify("JPY", 1))
print(f"recorded calls: [{', '.join(rates.calls)}]")

