// Jest has jest.fn() and mockReturnValue; this hand-written mock shows what such a library
// does, with Mockito's defaults for unstubbed calls.
class AssertionError extends Error {}

// The class under test only needs an object with rate(currency), so a test can hand it a fake.
// In production that object calls a slow, paid exchange-rate web API.
class Converter {
  constructor(rates) { this.rates = rates; }
  toUsd(amount, currency) { return amount * this.rates.rate(currency); }
}

// Records every call and answers with stubbed values, or a default (0.0) when not stubbed
class MockRateProvider {
  #stubs = new Map();
  calls = [];
  when(currency, value) { this.#stubs.set(currency, value); } // when(rates.rate(c)).thenReturn(v)
  rate(currency) {
    this.calls.push(currency);
    return this.#stubs.get(currency) ?? 0.0;
  }
  verify(currency, times) { // verify(rates, times(n)).rate(currency)
    const actual = this.calls.filter((c) => c === currency).length;
    if (actual !== times) {
      throw new AssertionError(actual === 0 ? `Wanted but not invoked: rates.rate("${currency}")`
        : `rates.rate("${currency}") wanted ${times} times but was ${actual}`);
    }
  }
}

function check(label, verification) {
  try { verification(); console.log(`${label}: passed`); }
  catch (e) { console.log(`${label}: FAILED ${e.message}`); }
}

const rates = new MockRateProvider();
rates.when('EUR', 1.10);
console.log('when(rates.rate("EUR")).thenReturn(1.10)');
const converter = new Converter(rates); // inject the mock

const eur = converter.toUsd(100.0, 'EUR');
console.log(`toUsd(100.00, "EUR") = ${eur.toFixed(2)}, within 1e-9 of 110.0: ${Math.abs(eur - 110.0) < 1e-9}`);
const gbp = converter.toUsd(100.0, 'GBP');
console.log(`toUsd(100.00, "GBP") = ${gbp.toFixed(2)}  <- unstubbed call returned the default 0.0`);

check('verify(rates).rate("EUR")', () => rates.verify('EUR', 1));
check('verify(rates, never()).rate("JPY")', () => rates.verify('JPY', 0));
check('verify(rates).rate("JPY")', () => rates.verify('JPY', 1));
console.log(`recorded calls: [${rates.calls.join(', ')}]`);

