import java.util.*;
import java.util.function.IntPredicate;

public class LeapYearTdd {
    record Case(int year, boolean expected) {}
    record Version(String name, IntPredicate isLeap) {}

    // Runs the whole suite against one implementation; returns the years that fail
    static List<Integer> failures(Version v, List<Case> suite) {
        List<Integer> failed = new ArrayList<>();
        for (Case c : suite) if (v.isLeap().test(c.year()) != c.expected()) failed.add(c.year());
        return failed;
    }

    static void run(String phase, Version v, List<Case> suite) {
        List<Integer> failed = failures(v, suite);
        String status = failed.isEmpty() ? "GREEN" : "RED  ";
        String detail = failed.isEmpty() ? "all " + suite.size() + " tests pass" : "failed " + failed;
        System.out.println("  " + phase + " " + status + " " + v.name() + ": " + detail);
    }

    public static void main(String[] args) {
        // Each implementation is the smallest change that makes the newest test pass
        Version v0 = new Version("v0 always false", y -> false);
        Version v1 = new Version("v1 divisible by 4", y -> y % 4 == 0);
        Version v2 = new Version("v2 by 4 but not by 100", y -> y % 4 == 0 && y % 100 != 0);
        Version v3 = new Version("v3 if-chain with 400 rule", y -> {
            if (y % 400 == 0) return true;
            if (y % 100 == 0) return false;
            return y % 4 == 0;
        });
        Version v4 = new Version("v4 one expression", y -> y % 4 == 0 && (y % 100 != 0 || y % 400 == 0));

        List<Case> suite = new ArrayList<>(List.of(new Case(2024, true), new Case(2023, false)));
        System.out.println("cycle 1: tests 2024 -> true, 2023 -> false");
        run("test first", v0, suite);   // red: the test must fail before the code exists
        run("make pass ", v1, suite);   // green: simplest code that passes

        suite.add(new Case(1900, false));
        System.out.println("cycle 2: add test 1900 -> false");
        run("test first", v1, suite);
        run("make pass ", v2, suite);

        suite.add(new Case(2000, true));
        System.out.println("cycle 3: add test 2000 -> true");
        run("test first", v2, suite);
        run("make pass ", v3, suite);

        System.out.println("refactor: same behavior, cleaner code, tests stay green");
        run("refactor  ", v4, suite);
    }
}

