#include <functional>
#include <iostream>
#include <string>
#include <utility>
#include <vector>

struct Version {
    std::string name;
    std::function<bool(int)> isLeap;
};
using Suite = std::vector<std::pair<int, bool>>;  // (year, expected)

// Runs the whole suite against one implementation; returns the years that fail
std::vector<int> failures(const Version& v, const Suite& suite) {
    std::vector<int> failed;
    for (const auto& [year, expected] : suite)
        if (v.isLeap(year) != expected) failed.push_back(year);
    return failed;
}

void run(const std::string& phase, const Version& v, const Suite& suite) {
    auto failed = failures(v, suite);
    std::cout << "  " << phase << (failed.empty() ? " GREEN " : " RED   ") << v.name << ": ";
    if (failed.empty()) {
        std::cout << "all " << suite.size() << " tests pass\n";
        return;
    }
    std::cout << "failed [";
    for (size_t i = 0; i < failed.size(); ++i) std::cout << (i ? ", " : "") << failed[i];
    std::cout << "]\n";
}

int main() {
    // Each implementation is the smallest change that makes the newest test pass
    Version v0{"v0 always false", [](int) { return false; }};
    Version v1{"v1 divisible by 4", [](int y) { return y % 4 == 0; }};
    Version v2{"v2 by 4 but not by 100", [](int y) { return y % 4 == 0 && y % 100 != 0; }};
    Version v3{"v3 if-chain with 400 rule", [](int y) {
        if (y % 400 == 0) return true;
        if (y % 100 == 0) return false;
        return y % 4 == 0;
    }};
    Version v4{"v4 one expression", [](int y) { return y % 4 == 0 && (y % 100 != 0 || y % 400 == 0); }};

    Suite suite = {{2024, true}, {2023, false}};
    std::cout << "cycle 1: tests 2024 -> true, 2023 -> false\n";
    run("test first", v0, suite);  // red: the test must fail before the code exists
    run("make pass ", v1, suite);  // green: simplest code that passes

    suite.push_back({1900, false});
    std::cout << "cycle 2: add test 1900 -> false\n";
    run("test first", v1, suite);
    run("make pass ", v2, suite);

    suite.push_back({2000, true});
    std::cout << "cycle 3: add test 2000 -> true\n";
    run("test first", v2, suite);
    run("make pass ", v3, suite);

    std::cout << "refactor: same behavior, cleaner code, tests stay green\n";
    run("refactor  ", v4, suite);
}

