import java.util.Objects;

class Solution {
    static String assertEquals(Object expected, Object actual) {
        // Objects.equals handles null on either side without throwing
        if (Objects.equals(expected, actual)) return "PASS";
        return "FAIL: expected: <" + expected + "> but was: <" + actual + ">";
    }
}

