class Solution {
    static boolean isLeapYear(int year) {
        if (year % 400 == 0) return true;    // 2000: century, but divisible by 400
        if (year % 100 == 0) return false;   // 1900, 2100: centuries are not leap years
        return year % 4 == 0;
    }
}

